/**
 * Lead detail page engine. GENERATED by tools/sync-opportunity-detail.mjs from web/pages/lead_detail.xhtml (+ components/lead_detail/*.xhtml, move_step_modal.xhtml, access_pop.xhtml) — do not edit; change the script and run `npm run opportunity-detail:sync`.
 *
 * The page script of the Java screen (lead_detail.xhtml: the stepbar, the five tabs, the history panel and table view, the contact
 * form with "forward to others", attachments …) and the scripts of its eleven modals (tag, sales owner, add product, history filter,
 * access, return step, close step group, close lead, next group, access popover, move step), same behaviour line by line, in ONE
 * scope like the global scope the Java scripts shared (a top-level function of the page is visible to the modals).
 *
 * WHY it is imperative DOM code and not Angular components: the Java page is a data-driven DOM application whose HTML is drawn from
 * API data as strings. Porting it 1:1 is what guarantees the screen, texts and states are identical to the production system; the
 * template (opportunity-detail.html) and stylesheets (opportunity-detail*.scss) are the Java markup / CSS verbatim and the engine binds to them
 * through the same ids / data-* contract as before.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java files (all of it lives in tools/sync-opportunity-detail.mjs, each swap with its reason):
 *   - the environment is injected (OpportunityDetailEnv): messages, fetch (the BFF contract — answered by the mock or by the live backend), the
 *     features the user has, the employee id, the address of the page, sessionStorage, the dialog library, navigation;
 *   - location.reload() is env.reload() (the host starts the page again with fresh data), window.open / location.href = … are
 *     env.open / env.navigate, navigator.sendBeacon is a POST through env.fetch;
 *   - global listeners, timers and animation frames are removed by the function returned from startOpportunityDetail(), and so is
 *     everything the scripts put on window and the nodes they moved out of the template (the update-confirm modal, the access popover);
 *   - the theme attribute is read from <html> (the Angular shell) instead of <body>.
 */

export interface OpportunityDetailEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** the BFF contract of the page: ../board/lead, ../board/activity-groups, ../board/prospect/… (paths exactly as the Java page wrote them) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** commonBean.hasFeature('CRM_…') */
  can: (feature: string) => boolean;
  /** the button registry (core/permissions/access-buttons.ts): may the signed-in user use this button? (the engine asks for PL-OP-DT-03, the "+" of the access rights) */
  access: (code: string) => boolean;
  /** commonBean.currentLang: 'th' | 'en' */
  lang: string;
  /** commonBean.ssEmployeeId — the id of the signed-in employee ('' when unknown) */
  employeeId: string;
  /** window.location.search: ?param_lead_id=…&activityGroupId=… */
  search: string;
  /** sessionStorage (tab state, table view flag of the page) */
  session: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;
  /** the dialog library of the Java template (SweetAlert) */
  swal: (options: unknown) => Promise<unknown>;
  /** window.location.href = url (a Java page link such as lead.face?… / sales_doc_rv.xhtml?…, turned into a route by the host) */
  navigate: (url: string) => void;
  /** window.open(url, target): a page link of the app opens its route, anything else is opened as it is */
  open: (url: string, target?: string) => void;
  /** location.reload(): the host starts the page again with fresh data */
  reload: () => void;
  /** history.replaceState with a new query string (never called by the page itself) */
  replaceQuery: (query: string) => void;
  /** the address an <img> loads a picture of the backend from (Java: ../docproxy?url=… for http(s):// pictures) */
  docProxy: (url: string) => string;
  /** a link of the Java app ("lead_detail.face?…") as the URL of its route — the href of the "go to lead" link */
  href: (javaLink: string) => string;
  /** where the static files of the Java app live: images/… of the Java web folder are served at `<assetBase>images/…` */
  assetBase: string;
}

