                /* live master-data loaders — cache ต่อ parent id กันยิงซ้ำ, คืน [] เสมอถ้า error/ไม่มีข้อมูล (ไม่ throw) */
                var _ld2ProvincesLivePromise = null;
                var _ld2DistrictsLiveCache = {}, _ld2SubsLiveCache = {};
                function ld2LoadProvincesLive() {
                    if (!_ld2ProvincesLivePromise)
                        _ld2ProvincesLivePromise = fetchJson('../board/provinces', []).then(_ld2Arr).catch(function () { return []; });
                    return _ld2ProvincesLivePromise;
                }
                function ld2LoadDistrictsLive(provinceId) {
                    if (!provinceId) return Promise.resolve([]);
                    var k = String(provinceId);
                    if (!_ld2DistrictsLiveCache[k])
                        _ld2DistrictsLiveCache[k] = fetchJson('../board/districts?provinceId=' + encodeURIComponent(provinceId), []).then(_ld2Arr).catch(function () { return []; });
                    return _ld2DistrictsLiveCache[k];
                }
                function ld2LoadSubsLive(districtId) {
                    if (!districtId) return Promise.resolve([]);
                    var k = String(districtId);
                    if (!_ld2SubsLiveCache[k])
                        _ld2SubsLiveCache[k] = fetchJson('../board/sub-districts?districtId=' + encodeURIComponent(districtId), []).then(_ld2Arr).catch(function () { return []; });
                    return _ld2SubsLiveCache[k];
                }
                /* เติม option แบบ key=code คง placeholder แรก — รองรับทั้ง item จาก live (id/code/name/nameTh)
                   และจาก bundle (code/name ล้วน) เก็บ id ไว้ใน data-id (ถ้ามี) ให้ cascade ระดับถัดไปอ่านต่อได้
                   + จำ list ที่ populate จริงไว้ใน _ld2SelectLists (ให้ _ldPutSel resolve id ตอน save ได้ตรงกับที่โชว์) */
                var _ld2SelectLists = {};
