                    var hidden = document.getElementById('ld2StepSelect');
                    var dd = document.getElementById('ld2StepDd');
                    if (dd) dd.querySelectorAll('.ld2-prod-dd-item').forEach(function (d) { d.classList.remove('ld2-dd-selected'); });
                    el.classList.add('ld2-dd-selected');
                    if (label) label.textContent = el.textContent.trim();
                    if (hidden) hidden.value = id || '';
                    window._ld2SelectedStepGroupId = groupId || '';   /* กลุ่มของ "ขั้นตอน" ที่เพิ่งเลือก — ดู ldSaveContactActivity */
                    if (dd) dd.classList.remove('show');
